package chat.cloudlet.securityaudit;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.webkit.*;import org.json.*;import java.lang.reflect.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
public final class SecurityAudit extends Instrumentation{
 public void onCreate(Bundle args){super.onCreate(args);start();}
 private Activity activity;private WebView web;
 private Object invoke(String name,Class<?>[] types,Object...args)throws Exception{Method m=activity.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}
 private WebResourceRequest request(String value){return new WebResourceRequest(){public Uri getUrl(){return Uri.parse(value);}public boolean isForMainFrame(){return true;}public boolean isRedirect(){return false;}public boolean hasGesture(){return false;}public String getMethod(){return "GET";}public Map<String,String> getRequestHeaders(){return Collections.emptyMap();}};}
 public void onStart(){Bundle result=new Bundle();try{getUiAutomation();activity=startActivitySync(new Intent().setClassName("chat.cloudlet.phone","chat.cloudlet.phone.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field f=activity.getClass().getDeclaredField("web");f.setAccessible(true);web=(WebView)f.get(activity);long end=System.currentTimeMillis()+30000;boolean loaded=false;while(!loaded&&System.currentTimeMillis()<end){CountDownLatch latch=new CountDownLatch(1);boolean[] ready={false};runOnMainSync(()->web.evaluateJavascript("Boolean(document.querySelector('.home-screen'))",v->{ready[0]="true".equals(v);latch.countDown();}));loaded=latch.await(2,TimeUnit.SECONDS)&&ready[0];if(!loaded)Thread.sleep(100);}if(!loaded)throw new AssertionError("Actual APK home did not become ready");
 JSONObject observations=new JSONObject();observations.put("uniqueLocalIPv6Allowed",invoke("allowed",new Class[]{URL.class},new URL("https://[fd00::1]/")));observations.put("publicIPv4Allowed",invoke("allowed",new Class[]{URL.class},new URL("https://8.8.8.8/")));observations.put("publicIPv6Allowed",invoke("allowed",new Class[]{URL.class},new URL("https://[2001:4860:4860::8888]/")));observations.put("loopbackAllowed",invoke("allowed",new Class[]{URL.class},new URL("https://127.0.0.1/")));observations.put("cgnatAllowed",invoke("allowed",new Class[]{URL.class},new URL("https://100.64.0.1/")));
 runOnMainSync(()->{try{ WebViewClient client=web.getWebViewClient();observations.put("normalOriginStatus",client.shouldInterceptRequest(web,request("https://appassets.androidplatform.net/index.html")).getStatusCode());observations.put("explicit443Status",client.shouldInterceptRequest(web,request("https://appassets.androidplatform.net:443/index.html")).getStatusCode());observations.put("wrongPortStatus",client.shouldInterceptRequest(web,request("https://appassets.androidplatform.net:444/index.html")).getStatusCode());observations.put("userinfoStatus",client.shouldInterceptRequest(web,request("https://user@appassets.androidplatform.net/index.html")).getStatusCode());
 observations.put("fileAccess",web.getSettings().getAllowFileAccess());observations.put("fileCrossOrigin",web.getSettings().getAllowFileAccessFromFileURLs());observations.put("universalFileAccess",web.getSettings().getAllowUniversalAccessFromFileURLs());}catch(Exception e){throw new RuntimeException(e);}});
 try{Intent intent=(Intent)invoke("externalIntent",new Class[]{String.class},"intent://music.example/#Intent;scheme=https;action=android.intent.action.SEND;launchFlags=0x3;end");observations.put("externalAction",intent.getAction());Intent music=(Intent)invoke("externalIntent",new Class[]{String.class},"orpheus://song/123");observations.put("musicScheme",music.getData().getScheme());Intent https=(Intent)invoke("externalIntent",new Class[]{String.class},"https://music.example/list");observations.put("httpsScheme",https.getData().getScheme());observations.put("externalGrantFlags",intent.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));boolean blocked=false;try{invoke("externalIntent",new Class[]{String.class},"intent://mark.via.phoneapi/external/private.txt#Intent;scheme=content;end");}catch(InvocationTargetException expected){blocked=true;}observations.put("contentIntentBlocked",blocked);}catch(NoSuchMethodException before){observations.put("externalIntentPolicyAvailable",false);}
 result.putString("observations",observations.toString());result.putString("result","completed");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("result","failed");result.putString("error",error.toString());finish(Activity.RESULT_CANCELED,result);}}
}
